import{_ as i,c as e,o as l,ag as t}from"./chunks/framework.DuVOYUUM.js";const p=JSON.parse('{"title":"Software Install Guide","description":"","frontmatter":{"order":1},"headers":[],"relativePath":"projects/igvc-2024/electrical/Software Install Guide.md","filePath":"projects/igvc-2024/electrical/Software Install Guide.md","lastUpdated":1790647345000}'),o={name:"projects/igvc-2024/electrical/Software Install Guide.md"};function s(n,a,r,d,h,c){return l(),e("div",null,a[0]||(a[0]=[t(`<h1 id="software-install-guide" tabindex="-1">Software Install Guide <a class="header-anchor" href="#software-install-guide" aria-label="Permalink to &quot;Software Install Guide&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#overview">Overview</a></li><li><a href="#arduino-ide">Arduino IDE</a><ul><li><a href="#step-1-download-arduino-ide">Step 1: Download Arduino IDE</a></li><li><a href="#step-2-install-arduino-ide">Step 2: Install Arduino IDE</a></li></ul></li><li><a href="#kicad">KiCad</a><ul><li><a href="#step-1-download-kicad-8-0">Step 1: Download KiCad 8.0</a></li><li><a href="#step-2-install-kicad-8-0">Step 2: Install KiCad 8.0</a></li></ul></li></ul></nav><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><h2 id="arduino-ide" tabindex="-1">Arduino IDE <a class="header-anchor" href="#arduino-ide" aria-label="Permalink to &quot;Arduino IDE&quot;">​</a></h2><p>The Arduino IDE is a software tool used for writing, compiling, and uploading code to Arduino boards. Follow these steps to install Arduino IDE on your computer:</p><h3 id="step-1-download-arduino-ide" tabindex="-1">Step 1: Download Arduino IDE <a class="header-anchor" href="#step-1-download-arduino-ide" aria-label="Permalink to &quot;Step 1: Download Arduino IDE&quot;">​</a></h3><ol><li>Visit the <a href="https://www.arduino.cc/en/software" target="_blank" rel="noreferrer">Arduino Software</a> download page.</li><li>Choose the appropriate version for your operating system (Windows, macOS, Linux).</li><li>Click on the download link to download the Arduino IDE installer.</li></ol><h3 id="step-2-install-arduino-ide" tabindex="-1">Step 2: Install Arduino IDE <a class="header-anchor" href="#step-2-install-arduino-ide" aria-label="Permalink to &quot;Step 2: Install Arduino IDE&quot;">​</a></h3><h4 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h4><ol><li>Once the download is complete, locate the downloaded installer file (usually a .exe file).</li><li>Double-click on the installer file to start the installation process.</li><li>Follow the on-screen instructions to complete the installation.</li><li>After installation, you may need to restart your computer.</li></ol><h4 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h4><ol><li>Locate the downloaded Arduino IDE disk image file (usually a .dmg file).</li><li>Double-click on the disk image file to mount it.</li><li>Drag the Arduino IDE application to your Applications folder to install it.</li><li>Eject the disk image after installation.</li></ol><h4 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h4><ol><li>To install the Arduino IDE 2 on Linux, first download the AppImage 64 bits (X86-64) from the <a href="https://www.arduino.cc/en/software" target="_blank" rel="noreferrer">Arduino Software page</a>.</li><li>Before we can launch the editor, we need to first make it an executable file. This is done by: <ul><li>Right-clicking the file</li><li>Choose <strong>Properties</strong></li><li>Select <strong>Permissions</strong></li><li>Rick the <strong>Allow executing file as program</strong> box.</li></ul></li><li>You can now double click the file to launch the Arduino IDE 2 on your Linux machine. In case you cannot run the AppImage file, make sure that FUSE is installed on your system. <ul><li>In Ubuntu (&gt;= 22.04):<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo add-apt-repository universe</span></span>
<span class="line"><span>sudo apt install libfuse2</span></span></code></pre></div></li><li>In Fedora<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dnf install fuse</span></span></code></pre></div></li><li>See instructions for installing FUSE on your distribution <a href="https://github.com/AppImage/AppImageKit/wiki/FUSE" target="_blank" rel="noreferrer">here</a>.</li><li>To enable the Arduino IDE to access the serial port and upload code to your board, the following rule can be added to <code> /etc/udev/rules.d/99-arduino.rules.</code><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SUBSYSTEMS==&quot;usb&quot;, ATTRS{idVendor}==&quot;2341&quot;, GROUP=&quot;plugdev&quot;, MODE=&quot;0666&quot;</span></span></code></pre></div></li></ul></li></ol><h4 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h4><p>Congratulations! You have successfully installed the Arduino IDE on your system.</p><h2 id="kicad" tabindex="-1">KiCad <a class="header-anchor" href="#kicad" aria-label="Permalink to &quot;KiCad&quot;">​</a></h2><h3 id="step-1-download-kicad-8-0" tabindex="-1">Step 1: Download KiCad 8.0 <a class="header-anchor" href="#step-1-download-kicad-8-0" aria-label="Permalink to &quot;Step 1: Download KiCad 8.0&quot;">​</a></h3><ol><li>Visit the <a href="https://www.kicad.org/download/" target="_blank" rel="noreferrer">KiCad Downloads</a> page.</li><li>Look for the KiCad 8.0 version compatible with your operating system.</li><li>Click on the download link to get the installer.</li></ol><h3 id="step-2-install-kicad-8-0" tabindex="-1">Step 2: Install KiCad 8.0 <a class="header-anchor" href="#step-2-install-kicad-8-0" aria-label="Permalink to &quot;Step 2: Install KiCad 8.0&quot;">​</a></h3><h4 id="windows-1" tabindex="-1">Windows <a class="header-anchor" href="#windows-1" aria-label="Permalink to &quot;Windows&quot;">​</a></h4><ol><li>Once the download is complete, locate the downloaded installer file (usually a .exe file).</li><li>Double-click on the installer file to start the installation process.</li><li>Follow the on-screen instructions provided by the installer.</li><li>Choose the installation directory and any additional options as needed.</li><li>Wait for the installation to complete.</li><li>After installation, you may need to restart your computer.</li></ol><h4 id="macos-1" tabindex="-1">macOS <a class="header-anchor" href="#macos-1" aria-label="Permalink to &quot;macOS&quot;">​</a></h4><ol><li>Locate the downloaded KiCad 8.0 disk image file (usually a .dmg file).</li><li>Double-click on the disk image file to mount it.</li><li>Drag the KiCad 8.0 application to your Applications folder to install it.</li><li>Eject the disk image after installation.</li></ol><h4 id="linux-1" tabindex="-1">Linux <a class="header-anchor" href="#linux-1" aria-label="Permalink to &quot;Linux&quot;">​</a></h4><ol><li><p>Open a terminal window.</p></li><li><p>Run the following command to add the KiCad repository:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-apt-repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ppa:kicad/kicad-8.0-releases</span></span></code></pre></div></li><li><p>After adding the repository, update the package list using the following command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div></li><li><p>Once the package list is updated, proceed to install KiCad by running:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kicad</span></span></code></pre></div><p>Follow any prompts or instructions that appear during the installation process.</p></li></ol><h4 id="conclusion-1" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion-1" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h4><p>Congratulations! You have successfully installed KiCad 8.0 on your system.</p>`,28)]))}const g=i(o,[["render",s]]);export{p as __pageData,g as default};
